INSERT INTO doctors (id, name, specialty, experience_years, experience_raw, degree, consultation_fee, consultation_fee_raw, rating, rating_raw, location, google_maps_link, coordinates, location_index, source_url, scraped_at, scraping_session, latitude, longitude) VALUES (571, 'Roshan Kumar.B', 'dermatologist', 21.0, '21 Years Experience Overall  (11 years as specialist)', 'MBBS, MD - Dermatology and Venerology', 600.0, '₹600', NULL, 'we had an appointment at 5.30pm. while taking the appointment some boy picked the call and said from 5pm clinic will be opened.  we reached there by 5.30 clinic was still closed so I had called the same number they said wait for 10 min doctor will come.  some girl was sitting over there she came to me suddenly and started fighting saying y did u tell clinic is closed aunty has to come so n so.  I don''t know who she is and who is the aunty.  I told it''s closed so I am just enquiring, she spoke very rudely.  later one aunty came and along with this gal she opened the door and started cleaning.  that gal was not at all answering for my queries about way of payment and all.  she was angry bcoz I had called n told clinic is closed.  even in second visit she has the grudge.  But the doctor ** **** **** *** well qualified. He has given treatment for a week and asked to consult again to change the medicine if required. *** *** ********* *** **** ***** *** waiting for the course to get completed. We are happy with the doctor n treatment.', 'Whitefield', 'http://www.google.com/maps/place/12.9623915843593,77.74796669519382', '12.9623915843593,77.74796669519382', 1, 'https://www.practo.com/bangalore/doctor/dr-roshan-kumar-r-dermatologist-dermatologist', '2025-09-04T23:35:41.190208', '20250904_223645', 12.9623915843593, 77.74796669519382);
